function donationYears(sups) {
    const set = new Set();
    for (const sp of sups) {
        for (const d of sp.donations)
            if (d.date)
                set.add(+String(d.date).slice(0, 4));
        if (sp.hist)
            for (const h of sp.hist)
                if (h.d)
                    set.add(+String(h.d).slice(0, 4));
    }
    return [...set].filter((y) => y > 1900 && y < 3000).sort((a, b) => b - a);
}
